1	export type Item = {
2	  type: string;
3	  cursed?: boolean;
4	  enchantment?: number;
5	};
6	
7	export type Customer = {
8	  yearsWithMHPCO: number;
9	};
10	
11	export type Damage = {
12	  itemType: string;
13	  amount: number;
14	};
15	
16	export type Incident = {
17	  cause: string;
18	  damages: Damage[];
19	};
20	
21	/**
22	 * One type covers both ops, so items/policy/incident are all optional. A
23	 * discriminated union on `op` would express this better, but the spec's
24	 * scenarios are plain object literals whose `op` widens to `string` and so
25	 * would no longer typecheck against literal `"quote"` / `"claim"` variants.
26	 * Revisit if a scenario parser ever narrows `op` on the way in.
27	 */
28	export type Step = {
29	  op: string;
30	  items?: Item[];
31	  policy?: number;
32	  incident?: Incident;
33	};
34	
35	export type Scenario = {
36	  customer: Customer;
37	  steps: Step[];
38	};
39	
40	export type QuoteResult = { premium: number };
41	export type ClaimResult = { payout: number; remainingCap: number };
42	
43	export type ScenarioResult = {
44	  results: (QuoteResult | ClaimResult)[];
45	};
46	
47	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
48	  sword: 100,
49	  amulet: 60,
50	  staff: 80,
51	  potion: 40,
52	  rune: 25,
53	  moonstone: 25,
54	};
55	/**
56	 * Deliberately NOT derived from the base premiums, though every entry today
57	 * happens to be 10x its counterpart. The MHPCO publishes two independent
58	 * price lists ("Sword: 1000 G insurance value, 100 G base premium"), and the
59	 * rules already pull them apart: the 3-alike building block cuts the base
60	 * premium to 60 G while the insurance value stays 250 G per component. Making
61	 * one a function of the other would encode a coincidence as a rule.
62	 */
63	const INSURANCE_VALUE_BY_ITEM_TYPE: Record<string, number> = {
64	  sword: 1000,
65	  amulet: 600,
66	  staff: 800,
67	  potion: 400,
68	  rune: 250,
69	  moonstone: 250,
70	};
71	const DEDUCTIBLE = 100;
72	const CAP_MULTIPLE = 2;
73	/** Governs PAYOUTS — distinct from the premium threshold of 5 below. */
74	const HIGH_ENCHANTMENT_PAYOUT_THRESHOLD = 8;
75	const HIGH_ENCHANTMENT_PAYOUT_PERCENT = 50;
76	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
77	const CURSE_SURCHARGE_PERCENT = 50;
78	const HIGH_ENCHANTMENT_THRESHOLD = 5;
79	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
80	const LOYALTY_THRESHOLD_YEARS = 2;
81	const LOYALTY_DISCOUNT_PERCENT = 20;
82	const FOLLOWUP_DISCOUNT_PERCENT = 15;
83	const PROCESSING_FEE = 5;
84	
85	const percentOf = (amount: number, percent: number): number =>
86	  (amount * percent) / 100;
87	
88	/**
89	 * Premiums round UP — the MHPCO's favour on money coming IN. Payouts will need
90	 * the opposite direction, so this deliberately names the premium case only
91	 * rather than a general "in the MHPCO's favour" rounding.
92	 */
93	const roundPremiumUp = (premium: number): number => Math.ceil(premium);
94	
95	const BLOCK_SIZE = 3;
96	const BLOCK_BASE_PREMIUM = 60;
97	
98	/** Counts of items of the same type — "alike" in the MHPCO's terms. */
99	const countAlikeItems = (items: Item[]): Map<string, number> =>
100	  items.reduce(
101	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
102	    new Map<string, number>(),
103	  );
104	
105	const formsBuildingBlock = (count: number): boolean => count === BLOCK_SIZE;
106	
107	const basePremiumForAlikeItems = (type: string, count: number): number =>
108	  formsBuildingBlock(count)
109	    ? BLOCK_BASE_PREMIUM
110	    : count * BASE_PREMIUM_BY_ITEM_TYPE[type];
111	
112	const policyBasePremium = (items: Item[]): number =>
113	  [...countAlikeItems(items)].reduce(
114	    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
115	    0,
116	  );
117	
118	const itemBasePremium = (item: Item): number =>
119	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
120	
121	const isHighlyEnchanted = (item: Item): boolean =>
122	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
123	
124	/** Item-specific surcharges stack additively. */
125	const itemSurchargePercent = (item: Item): number =>
126	  (item.cursed ? CURSE_SURCHARGE_PERCENT : 0) +
127	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0);
128	
129	/**
130	 * Item-specific modifiers are percentages of the AFFECTED ITEM's own base
131	 * premium — unlike policy-wide modifiers, which apply to the policy base.
132	 */
133	const totalItemSurcharges = (items: Item[]): number =>
134	  items.reduce(
135	    (total, item) =>
136	      total + percentOf(itemBasePremium(item), itemSurchargePercent(item)),
137	    0,
138	  );
139	
140	const isLongStanding = (customer: Customer): boolean =>
141	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
142	
143	/**
144	 * The net of all policy-wide percentages. Policy-wide modifiers are
145	 * percentages of the POLICY base premium — unlike item-specific modifiers,
146	 * which apply to the affected item's own base. The net is negative when the
147	 * discounts outweigh the surcharges: a long-standing customer nets -10 %.
148	 */
149	const netPolicyAdjustmentPercent = (
150	  customer: Customer,
151	  precedingSteps: number,
152	): number =>
153	  FIRST_INSURANCE_SURCHARGE_PERCENT -
154	  (isLongStanding(customer) ? LOYALTY_DISCOUNT_PERCENT : 0) -
155	  // The follow-up discount is owed on every quote after the customer's FIRST
156	  // QUOTE, but what we have here is a count of preceding STEPS. The two
157	  // coincide only because every step exercised so far is a quote; once claim
158	  // steps arrive, [quote, claim, quote] will wrongly discount the third step
159	  // as a second follow-up. No test forces the distinction yet.
160	  (precedingSteps > 0 ? FOLLOWUP_DISCOUNT_PERCENT : 0);
161	
162	const policyAdjustment = (
163	  policyBase: number,
164	  customer: Customer,
165	  precedingSteps: number,
166	): number =>
167	  percentOf(policyBase, netPolicyAdjustmentPercent(customer, precedingSteps));
168	
169	const quotePremium = (
170	  items: Item[],
171	  customer: Customer,
172	  precedingSteps: number,
173	): number => {
174	  const basePremium = policyBasePremium(items);
175	  return roundPremiumUp(
176	    basePremium +
177	      totalItemSurcharges(items) +
178	      policyAdjustment(basePremium, customer, precedingSteps) +
179	      PROCESSING_FEE,
180	  );
181	};
182	
183	const roundPayoutDown = (payout: number): number => Math.floor(payout);
184	
185	const insuranceSum = (items: Item[]): number =>
186	  items.reduce((sum, item) => sum + INSURANCE_VALUE_BY_ITEM_TYPE[item.type], 0);
187	
188	const damagedItem = (damage: Damage, policyItems: Item[]): Item | undefined =>
189	  policyItems.find((item) => item.type === damage.itemType);
190	
191	const isHighlyEnchantedForPayout = (item: Item | undefined): boolean =>
192	  (item?.enchantment ?? 0) >= HIGH_ENCHANTMENT_PAYOUT_THRESHOLD;
193	
194	/**
195	 * What the MHPCO reimburses for ONE damaged item, before the deductible.
196	 * Highly enchanted items are reimbursed at half the damage amount.
197	 */
198	const reimbursementFor = (damage: Damage, policyItems: Item[]): number =>
199	  isHighlyEnchantedForPayout(damagedItem(damage, policyItems))
200	    ? percentOf(damage.amount, HIGH_ENCHANTMENT_PAYOUT_PERCENT)
201	    : damage.amount;
202	
203	/** The deductible applies once per damaged item, not once per incident. */
204	const totalReimbursement = (incident: Incident, policyItems: Item[]): number =>
205	  incident.damages.reduce(
206	    (total, damage) =>
207	      total + reimbursementFor(damage, policyItems) - DEDUCTIBLE,
208	    0,
209	  );
210	
211	/** A claim's `policy` field is the index of the quote step that wrote it. */
212	const itemsCoveredBy = (policy: number, scenario: Scenario): Item[] =>
213	  scenario.steps[policy].items ?? [];
214	
215	/** The MHPCO caps a policy at twice its insurance sum. */
216	const capFor = (policyItems: Item[]): number =>
217	  CAP_MULTIPLE * insuranceSum(policyItems);
218	
219	const claimResult = (step: Step, scenario: Scenario): ClaimResult => {
220	  const policyItems = itemsCoveredBy(step.policy ?? 0, scenario);
221	  const cap = capFor(policyItems);
222	  // Non-null: runScenario only routes here when op === "claim", and every
223	  // claim step carries an incident. See the Step doc comment.
224	  const payout = roundPayoutDown(
225	    totalReimbursement(step.incident!, policyItems),
226	  );
227	  return { payout, remainingCap: cap - payout };
228	};
229	
230	export const runScenario = (scenario: Scenario): ScenarioResult => ({
231	  results: scenario.steps.map((step, precedingSteps) =>
232	    step.op === "claim"
233	      ? claimResult(step, scenario)
234	      : {
235	          premium: quotePremium(
236	            step.items ?? [],
237	            scenario.customer,
238	            precedingSteps,
239	          ),
240	        },
241	  ),
242	});
